#!/usr/bin/env python3
"""Generates null_webgpu_stubs.cpp: a definition for every WebGPU C function in
dawn/webgpu.h that null_webgpu.cpp does not define by hand.

  gen_stubs.py <include/dawn/webgpu.h> <null_webgpu.cpp> <out.cpp>

Defaults: AddRef/Release count references; a function returning an object makes a
new one; WGPUStatus returns Success; anything else returns zero. A future that a
stub returns is never completed, so asynchronous calls belong in the hand-written
file (the generated file lists them so they are easy to find).
"""
import re
import sys

header_path, manual_path, out_path = sys.argv[1:4]
header = open(header_path, encoding="utf-8").read()
manual = open(manual_path, encoding="utf-8").read()

handles = set(re.findall(r"typedef struct (WGPU\w+)Impl\* WGPU\w+", header))
start = header.index("#if !defined(WGPU_SKIP_DECLARATIONS)")
end = header.index("#endif  // !defined(WGPU_SKIP_DECLARATIONS)")
decl_re = re.compile(r"^WGPU_EXPORT (.+?)\b(wgpu\w+)\((.*)\) WGPU_FUNCTION_ATTRIBUTE;$", re.M)
# Definitions in the hand-written file start at column 0; calls inside bodies are indented.
manual_defs = set(re.findall(r"^\S.*?\b(wgpu[A-Z]\w*)\(", manual, re.M))

out = [
    "// Generated by gen_stubs.py from Dawn's webgpu.h. Do not edit: define a function",
    "// in null_webgpu.cpp instead, and the generator leaves it out of this file.",
    "",
    '#include "null_webgpu.hpp"',
    "",
    '#pragma GCC diagnostic ignored "-Wunused-parameter"',
    "",
    'extern "C" {',
    "",
]
futures = []
count = 0
for ret, name, params in decl_re.findall(header[start:end]):
    if name in manual_defs:
        continue
    ret = ret.replace("WGPU_NULLABLE ", "").strip()
    params = params.replace("WGPU_NULLABLE ", "")
    m = re.fullmatch(r"wgpu(\w+?)(AddRef|Release)", name)
    if m and ("WGPU" + m.group(1)) in handles and ret == "void":
        op = "ref" if m.group(2) == "AddRef" else "unref"
        body = f"if (object != nullptr) {{ object->{op}(); }}"
        params = f"WGPU{m.group(1)} object"
    elif ret == "void":
        body = ""
    elif ret in handles:
        body = f"return new {ret}Impl;"
    elif ret == "WGPUFuture":
        body = "return WGPUFuture{0};"
        futures.append(name)
    elif ret == "WGPUStatus":
        body = "return WGPUStatus_Success;"
    else:
        body = "return {};"
    out.append(f"{ret} {name}({params}) {{ {body} }}".replace("{  }", "{}"))
    count += 1
out += ["", '} // extern "C"', ""]
if futures:
    out.insert(3, "// Futures these stubs never complete: " + ", ".join(futures))
open(out_path, "w", encoding="utf-8", newline="\n").write("\n".join(out))
print(f"gen_stubs: {count} stubs, {len(manual_defs)} hand-written, {len(futures)} uncompleted futures")
